// And groups predicates with the AND operator between them.
func And(predicates ...predicate.XGcalConnection) predicate.XGcalConnection {
	return predicate.XGcalConnection(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.XGcalConnection) predicate.XGcalConnection {
	return predicate.XGcalConnection(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.XGcalConnection) predicate.XGcalConnection {
	return predicate.XGcalConnection(sql.NotPredicates(p))
}
